method Strongest_Extension(class_name: string, extensions: seq<string>) returns (result: string)
    requires class_name != ""
    requires extensions != []
    ensures result == class_name + "." + strongestExtension
    ensures strongestExtension == extensions[strongestIndex]
    ensures |extensions| > strongestIndex >= 0
    ensures forall i :: 0 <= i < |extensions| ==> 
        (Strength(extensions[i]) < Strength(strongestExtension) => i > strongestIndex)
{
    var strongestIndex := 0;
    var strongestExtension := extensions[0];
    var strongestStrength := Strength(strongestExtension);

    var i := 1;
    while i < |extensions|
        invariant 0 <= i <= |extensions|
        invariant strongestIndex < |extensions|
        invariant strongestStrength == Strength(strongestExtension)
    {
        if Strength(extensions[i]) > strongestStrength {
            strongestIndex := i;
            strongestExtension := extensions[i];
            strongestStrength := Strength(strongestExtension);
        }
        i := i + 1;
    }

    result := class_name + "." + strongestExtension;
}

method Strength(extension: string) returns (strength: int)
    ensures strength == CountUppercase(extension) - CountLowercase(extension)
{
    var upperCount := CountUppercase(extension);
    var lowerCount := CountLowercase(extension);
    strength := upperCount - lowerCount;
}

method CountUppercase(s: string) returns (count: int)
    ensures count == |{ c | c in s && IsUpper(c) }|
{
    count := 0;
    var i := 0;
    while i < |s| 
        invariant 0 <= i <= |s|
        invariant count == |{ c | j | 0 <= j < i && IsUpper(s[j]) }|
    {
        if IsUpper(s[i]) {
            count := count + 1;
        }
        i := i + 1;
    }
}

method CountLowercase(s: string) returns (count: int)
    ensures count == |{ c | c in s && IsLower(c) }|
{
    count := 0;
    var i := 0;
    while i < |s| 
        invariant 0 <= i <= |s|
        invariant count == |{ c | j | 0 <= j < i && IsLower(s[j]) }|
    {
        if IsLower(s[i]) {
            count := count + 1;
        }
        i := i + 1;
    }
}

method IsUpper(c: char) returns (result: bool)
    ensures result <=> (c >= 'A' && c <= 'Z')
{
    result := c >= 'A' && c <= 'Z';
}

method IsLower(c: char) returns (result: bool)
    ensures result <=> (c >= 'a' && c <= 'z')
{
    result := c >= 'a' && c <= 'z';
}
